  pfWebFeatProduct: 'Manajemen Produk & Stok',
  pfWebFeatProductDesc: 'Kelola produk, varian, harga, stok, kategori, dan bundle — update langsung tampil di App Kasir',
  pfWebFeatReports: 'Laporan Keuangan & Shift',
  pfWebFeatReportsDesc: 'Laporan penjualan harian/bulanan, rekap per shift, produk terlaris, dan analitik tren pendapatan',
  pfWebFeatInsights: 'Smart Insights',
  pfWebFeatInsightsDesc: 'Insight otomatis: produk lambat, jam paling ramai, margin per produk — tanpa perlu pivot sendiri',
  pfWebFeatPromo: 'Promo & Diskon',
  pfWebFeatPromoDesc: 'Atur diskon produk, promo nominal, dan aturan harga khusus — berlaku otomatis di semua kasir',
  pfWebFeatStaff: 'Manajemen Karyawan & Absensi',
  pfWebFeatStaffDesc: 'Tambah karyawan, atur role, lihat riwayat absensi clock-in/out dari kiosk kasir',
  pfWebFeatRbac: 'Hak Akses (RBAC)',
  pfWebFeatRbacDesc: 'Atur role granular: kasir hanya transaksi, gudang hanya stok, koki hanya KDS, manager lihat laporan',
  pfWebFeatMultiOutlet: 'Multi Outlet',
  pfWebFeatMultiOutletDesc: 'Kelola semua cabang dari satu akun — stok, laporan, dan karyawan terpisah per outlet',
  pfWebFeatOutletSettings: 'Setting Outlet & Struk',
  pfWebFeatOutletSettingsDesc: 'Konfigurasi terminal, meja, metode bayar, logo struk, pajak, nomor antrian per outlet',
  pfLevelInsightsDesc: '"Produk ini jarang laku" · "Jam 7–9 paling ramai" · "Margin turun minggu ini" — tersedia di dashboard',
  pfLevelMultiOutlet: 'Multi Outlet Control',
  pfLevelMultiOutletDesc: 'Monitor semua cabang dari satu akun · Bandingkan performa antar outlet · Stok & laporan terpisah',
  pfSetup1: 'Daftar & Login Web Admin',
  pfSetup1Desc: 'Owner daftar via email+password. Set nama bisnis, tipe usaha (FNB/Retail/Jasa).',
  pfSetup2Desc: 'Buat minimal 1 outlet (lokasi toko). Setiap outlet punya stok & data sendiri.',
  pfSetup3: 'Tambah Karyawan & Atur Role',
  pfSetup3Desc: 'Buat akun karyawan (Kasir, Koki, Gudang). Atur role → otomatis mengunci fitur yang tidak relevan.',
  pfSetup4: 'Input Produk & Stok',
  pfSetup4Desc: 'Tambah produk, varian, harga, kategori, diskon. Stok akan muncul otomatis di App Kasir.',
  pfSetup5: 'Bind Terminal di App Kasir',
  pfSetup5Desc: 'Owner login di tablet/HP kasir → pilih outlet → pilih terminal → sistem terikat ke perangkat ini.',
  pfSetup6: 'Kasir Login PIN & Buka Shift',
  pfSetup6Desc: 'Setiap hari kasir login dengan PIN 4-digit → input kas awal → shift terbuka → siap transaksi.',
  pfDaily1: 'Login PIN Harian',
  pfDaily1Desc: 'Kasir masukkan PIN 4-digit. Jika shift belum ada, langsung diminta buka shift & input kas awal.',
  pfDaily2: 'Proses Order',
  pfDaily2Desc: 'Pilih produk → tambah ke keranjang → pilih tipe order (makan di tempat/bawa pulang/delivery).',
  pfDaily3: 'Pembayaran & Struk',
  pfDaily3Desc: 'Pilih metode bayar → input nominal → cetak struk otomatis. Stok berkurang real-time.',
  pfDaily4: 'Kunci Kasir (Ganti Shift)',
  pfDaily4Desc: 'Tap "Kunci Kasir" → layar PIN muncul. Kasir berikutnya login PIN tanpa perlu setup ulang.',
  pfDaily5: 'Tutup Shift',
  pfDaily5Desc: 'Akhir shift: tutup shift → hitung kas akhir → laporan shift tersimpan & bisa dilihat di Web Admin.',
  pfDaily6: 'Pantau Laporan di Web',
  pfDaily6Desc: 'Owner buka Web Admin → dashboard → laporan keuangan per shift → analitik tren → tidak perlu di toko.',
  pfFaq1Q: 'Apa bedanya App Kasir dan Web Admin?',
  pfFaq2Q: 'Apakah kasir perlu login ulang setiap hari?',
  pfFaq2A: 'Tidak. Perangkat terikat ke terminal secara permanen. Kasir hanya perlu memasukkan PIN 4-digit setiap kali membuka sesi. PIN berbeda per karyawan — owner tidak perlu terlibat sama sekali untuk operasi harian.',
  pfFaq3Q: 'Apa itu "Terminal" dan kenapa perlu di-bind?',
  pfFaq3A: 'Terminal adalah identitas perangkat kasir (tablet/HP). Proses bind menghubungkan perangkat fisik ke satu terminal di sistem — memastikan data shift, stok, dan struk terikat ke lokasi yang benar. Satu perangkat = satu terminal.',
  pfFaq4Q: 'Bagaimana kalau ada 2 kasir yang bergantian di 1 perangkat?',
  pfFaq4A: 'Gunakan fitur "Kunci Kasir" — layar kembali ke PIN. Kasir berikutnya login dengan PIN-nya sendiri dan shift baru terbuka secara otomatis. Data setiap kasir terpisah per sesi shift.',
  pfFaq5Q: 'Apakah stok bisa dikelola per outlet?',
  pfFaq5A: 'Ya. Setiap outlet memiliki stok sendiri. Stok otomatis berkurang setiap transaksi di outlet tersebut. Untuk memindahkan stok antar outlet, gunakan fitur Transfer Stok di menu Inventori.',
  pfFaq6Q: 'Siapa saja yang bisa akses Web Admin?',
  pfFaq6A: 'Owner dan Manager bisa mengakses semua fitur termasuk laporan keuangan dan RBAC. Kasir/Koki/Gudang login via App, bukan Web Admin. Kasir dengan akses web hanya bisa lihat dashboard dan transaksi.',
  pfFaq7Q: 'Apakah bisa multi-outlet dari satu akun?',
  pfFaq7A: 'Ya. Satu akun Owner bisa mengelola banyak outlet. Di Web Admin ada filter outlet — tampilkan data outlet tertentu atau semua outlet sekaligus. Masing-masing outlet punya terminal, stok, dan shift sendiri.',
  pfFaq8Q: 'Apa yang terjadi kalau koneksi internet terputus saat transaksi?',
  pfFaq8A: 'App Kasir menyimpan data sesi lokal. Transaksi yang sudah diproses tetap tersimpan. Saat koneksi kembali, data akan disinkronkan ke server. Laporan di Web Admin akan diperbarui otomatis.',
